class AgentLifecycle:
    def _generate_llm_prompt(self, goal: str, sample_input: str) -> str:

        # Define the PROMPT_ENGINEERING_SYSTEM_PROMPT and PROMPT_ENGINEERING_TEMPLATE
        PROMPT_ENGINEERING_SYSTEM_PROMPT = "You are a helpful assistant."
        PROMPT_ENGINEERING_TEMPLATE = "Generate a helpful and informative prompt for the given goal: {goal}\\nContext: {context}"

        # Create the messages list
        messages = [
            {"role": "system", "content": PROMPT_ENGINEERING_SYSTEM_PROMPT},
            {"role": "user", "content": PROMPT_ENGINEERING_TEMPLATE.format(goal=goal, context=sample_input)}
        ]

        # Call the chat_completion method of openai_wrapper with the messages list
        try:
            completion = openai_wrapper.chat_completion(messages)
        except Exception as e:
            print(f"Error generating LLM prompt: {e}")
            completion = ""

        # Return the generated prompt
        return completion
