def generate_safe_fn(f, safe_range_fn):
  """
  Generates a function with a safe input range.
  """
  def safe_f(*args, **kwargs):
    def cond(x):
      return jnp.less_equal(x, safe_range_fn[-1]) & jnp.less(safe_range_fn[0], x)
    x = jnp.where(cond(args[0]), safe_range_fn[0], args[0])
    return f(*(x,) + args[1:], **kwargs)
  return safe_f

@custom_jvp
def safe_log1p(x):
  """
  The safe_log1p function computes the natural logarithm of 1 plus the input value, x,
  while ensuring that the input value is within a safe range to avoid numerical errors
  or undefined behavior.
  """
  return generate_safe_fn(jnp.log1p, (-np.nextafter(np.float32(-1), 0), np.float32(1000)))

def safe_log1p_jvp(primals, tangents):
  x, = primals
  x_dot, = tangents
  return jnp.log1p(x), x_dot / (1 + x)
